DO $$ DECLARE d text; BEGIN SELECT pg_get_constraintdef(oid) INTO STRICT d FROM pg_constraint WHERE conrelid='cmd_command'::regclass AND conname='cmd_command_command_type_check'; ALTER TABLE cmd_command DROP CONSTRAINT cmd_command_command_type_check; EXECUTE format('ALTER TABLE cmd_command ADD CONSTRAINT cmd_command_command_type_check %s',replace(d,'CHECK (','CHECK (command_type=''assign_actor_language'' OR ')); END $$;
CREATE TABLE camp_language(language_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,public_id uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,campaign_id bigint NOT NULL REFERENCES camp_campaign(campaign_id),language_code text NOT NULL CHECK(language_code~'^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$'),name text NOT NULL CHECK(btrim(name)<>''),UNIQUE(campaign_id,language_code),UNIQUE(language_id,campaign_id));
CREATE TABLE actor_language_proficiency(actor_id bigint NOT NULL,language_id bigint NOT NULL,campaign_id bigint NOT NULL,proficiency_kind text NOT NULL CHECK(proficiency_kind IN('native','additional')),can_speak boolean NOT NULL,can_read boolean NOT NULL,can_write boolean NOT NULL,source_command_id bigint NOT NULL UNIQUE REFERENCES cmd_command(command_id),PRIMARY KEY(actor_id,language_id),FOREIGN KEY(actor_id,campaign_id) REFERENCES actor_actor(actor_id,campaign_id),FOREIGN KEY(language_id,campaign_id) REFERENCES camp_language(language_id,campaign_id),CHECK((proficiency_kind='native' AND can_speak AND can_read AND NOT can_write) OR (proficiency_kind='additional' AND NOT can_speak AND can_read AND can_write)));
CREATE UNIQUE INDEX actor_one_native_language ON actor_language_proficiency(actor_id) WHERE proficiency_kind='native';
CREATE TABLE cmd_actor_language_receipt(command_id bigint PRIMARY KEY REFERENCES cmd_command(command_id),actor_id bigint NOT NULL REFERENCES actor_actor(actor_id),language_id bigint NOT NULL REFERENCES camp_language(language_id),proficiency_kind text NOT NULL,linguistics_level smallint,CHECK((proficiency_kind='native' AND linguistics_level IS NULL) OR (proficiency_kind='additional' AND linguistics_level>=1)));
CREATE FUNCTION cmd_reject_actor_language_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Actor language records are immutable'; END $$;
CREATE TRIGGER actor_language_immutable BEFORE UPDATE OR DELETE ON actor_language_proficiency FOR EACH ROW EXECUTE FUNCTION cmd_reject_actor_language_mutation();CREATE TRIGGER cmd_actor_language_immutable BEFORE UPDATE OR DELETE ON cmd_actor_language_receipt FOR EACH ROW EXECUTE FUNCTION cmd_reject_actor_language_mutation();
